\begin{array}{c}
\vec{a} \cdot \vec{b}=\left(x_{1} \overrightarrow{e_{1}}+y_{1} \overrightarrow{e_{2}}\right) \cdot\left(x_{2} \overrightarrow{e_{1}}+y_{2} \overrightarrow{e_{2}}\right) \\
=x_{1} x_{2} \overrightarrow{e_{1}} \cdot \overrightarrow{e_{1}}+x_{1} y_{2} \overrightarrow{e_{1}} \cdot \overrightarrow{e_{2}}+y_{1} x_{2} \overrightarrow{e_{2}} \cdot \overrightarrow{e_{1}}+y_{1} y_{2} \overrightarrow{e_{2}} \cdot \overrightarrow{e_{2}} \\
=x_{1} x_{2}+y_{1} y_{2}
\end{array}
